IF OBJECT_ID(N'[magnetmail].[User]', N'U') IS NULL
CREATE TABLE [magnetmail].[User] (
    [hasEmail] NVARCHAR(MAX) NULL,
    [web_version] NVARCHAR(MAX) NULL,
    [req_billing_initials] NVARCHAR(MAX) NULL,
    [billing_name] NVARCHAR(255) NULL,
    [User_Id] NVARCHAR(255) NULL,
    [newsletter_permission] NVARCHAR(MAX) NULL,
    [insertTextUnsubscribe] NVARCHAR(MAX) NULL,
    [hasForms] NVARCHAR(MAX) NULL,
    [FilterOutGroupsOnSend] NVARCHAR(MAX) NULL,
    [User_Nbr] NVARCHAR(255) NULL,
    [UploadSystemVersion] NVARCHAR(255) NULL,
    [req_billing_code] NVARCHAR(MAX) NULL,
    [dynamic_content_permission] NVARCHAR(MAX) NULL,
    [unsubscribe_type] NVARCHAR(255) NULL,
    [enable_ignore_dedupe] NVARCHAR(MAX) NULL,
    [CampaignManager_permission] NVARCHAR(MAX) NULL,
    [hasFax] NVARCHAR(MAX) NULL,
    [hasCustomId] NVARCHAR(MAX) NULL,
    [event_permission] NVARCHAR(MAX) NULL,
    [rss_permission] NVARCHAR(MAX) NULL,
    [email_notification_permission] NVARCHAR(MAX) NULL,
    [messageCategory] NVARCHAR(MAX) NULL,
    [__mj_integration_SyncStatus] NVARCHAR(50) NOT NULL DEFAULT 'Active',
    [__mj_integration_LastSyncedAt] DATETIMEOFFSET NULL,
    [__mj_integration_LastSyncedSnapshot] NVARCHAR(MAX) NULL,
    [__mj_integration_SyncMessage] NVARCHAR(MAX) NULL,
    [__mj_integration_ContentHash] NVARCHAR(64) NULL,
    [__mj_integration_CustomOverflow] NVARCHAR(MAX) NULL,
    [__mj_integration_ExternalVersion] NVARCHAR(255) NULL,
    [__mj_integration_LastSeenModifiedValue] NVARCHAR(255) NULL,
    [__mj_integration_LastReconciledAt] DATETIMEOFFSET NULL,
    [__mj_integration_LastWriterDirection] NVARCHAR(10) NULL,
    [__mj_integration_IsTombstoned] BIT NOT NULL DEFAULT 0,
    [__mj_integration_DeletedDetectedAt] DATETIMEOFFSET NULL
);

